import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"11、【泰】 乾下坤上","description":"橫渠易說 - 11、【泰】 乾下坤上","frontmatter":{"title":"11、【泰】 乾下坤上","description":"橫渠易說 - 11、【泰】 乾下坤上"},"headers":[],"relativePath":"classics/hengqu/013.md","filePath":"classics/hengqu/013.md"}'),l={name:"classics/hengqu/013.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_11、【泰】-乾下坤上" tabindex="-1">11、【泰】 乾下坤上 <a class="header-anchor" href="#_11、【泰】-乾下坤上" aria-label="Permalink to “11、【泰】 乾下坤上”">​</a></h1><h3 id="彖曰-泰小往大來吉亨-則是天地交而萬物通也-上下交而其志同也。內陽而外陰-內健而外順-內君子而外小人-君子道長-小人道消也。" tabindex="-1">彖曰：“泰小往大來吉亨”，則是天地交而萬物通也，上下交而其志同也。內陽而外陰，內健而外順，內君子而外小人，君子道長，小人道消也。 <a class="header-anchor" href="#彖曰-泰小往大來吉亨-則是天地交而萬物通也-上下交而其志同也。內陽而外陰-內健而外順-內君子而外小人-君子道長-小人道消也。" aria-label="Permalink to “彖曰：“泰小往大來吉亨”，則是天地交而萬物通也，上下交而其志同也。內陽而外陰，內健而外順，內君子而外小人，君子道長，小人道消也。”">​</a></h3><h3 id="象曰-天地交-泰-後以財成天地之道-輔相天地之宜-以左右民。" tabindex="-1">象曰：天地交，泰，後以財成天地之道，輔相天地之宜，以左右民。 <a class="header-anchor" href="#象曰-天地交-泰-後以財成天地之道-輔相天地之宜-以左右民。" aria-label="Permalink to “象曰：天地交，泰，後以財成天地之道，輔相天地之宜，以左右民。”">​</a></h3><h3 id="初九-拔茅茹-以其匯徵-吉。-象曰-拔茅徵吉-志在外也。" tabindex="-1">初九，拔茅茹，以其匯徵，吉。 象曰：拔茅徵吉，志在外也。 <a class="header-anchor" href="#初九-拔茅茹-以其匯徵-吉。-象曰-拔茅徵吉-志在外也。" aria-label="Permalink to “初九，拔茅茹，以其匯徵，吉。 象曰：拔茅徵吉，志在外也。”">​</a></h3><h3 id="九二-包荒-用馮河-不遐遺-朋亡-得尚於中行。-象曰-包荒-得尚於中行-以光大也。" tabindex="-1">九二，包荒，用馮河，不遐遺，朋亡，得尚於中行。 象曰：“包荒，得尚於中行”，以光大也。 <a class="header-anchor" href="#九二-包荒-用馮河-不遐遺-朋亡-得尚於中行。-象曰-包荒-得尚於中行-以光大也。" aria-label="Permalink to “九二，包荒，用馮河，不遐遺，朋亡，得尚於中行。 象曰：“包荒，得尚於中行”，以光大也。”">​</a></h3><p>中行，中立之行也，若朋比則未足尚也。舜文之大，不是過也。</p><h3 id="九三-無平不陂-無往不復-艱貞無咎。勿恤其孚-於食有福。-象曰-無往不復-天地際也。" tabindex="-1">九三，無平不陂，無往不復，艱貞無咎。勿恤其孚，於食有福。 象曰：“無往不復”，天地際也。 <a class="header-anchor" href="#九三-無平不陂-無往不復-艱貞無咎。勿恤其孚-於食有福。-象曰-無往不復-天地際也。" aria-label="Permalink to “九三，無平不陂，無往不復，艱貞無咎。勿恤其孚，於食有福。 象曰：“無往不復”，天地際也。”">​</a></h3><p>因交與之際以著戒，能艱貞則享福可必。</p><h3 id="六四-翩翩-不富以其鄰-不戒以孚。-象曰-翩翩-不富-皆失實也。-不戒以孚-中心願也。" tabindex="-1">六四，翩翩，不富以其鄰，不戒以孚。 象曰：“翩翩”“不富”，皆失實也。“不戒以孚”，中心願也。 <a class="header-anchor" href="#六四-翩翩-不富以其鄰-不戒以孚。-象曰-翩翩-不富-皆失實也。-不戒以孚-中心願也。" aria-label="Permalink to “六四，翩翩，不富以其鄰，不戒以孚。 象曰：“翩翩”“不富”，皆失實也。“不戒以孚”，中心願也。”">​</a></h3><p>陰陽皆未安其分，故家不富，志不寧。</p><h3 id="六五-帝乙歸妹-以祉元吉。-象曰-以祉元吉-中以行願也。" tabindex="-1">六五，帝乙歸妹，以祉元吉。 象曰：“以祉元吉”，中以行願也。 <a class="header-anchor" href="#六五-帝乙歸妹-以祉元吉。-象曰-以祉元吉-中以行願也。" aria-label="Permalink to “六五，帝乙歸妹，以祉元吉。 象曰：“以祉元吉”，中以行願也。”">​</a></h3><p>雖陰陽義反，取交際為大義。</p><h3 id="上六-城復於隍-勿用師。自邑告命-貞吝。-象曰-城復於隍-其命亂也。" tabindex="-1">上六，城復於隍，勿用師。自邑告命，貞吝。 象曰：“城復於隍”，其命亂也。 <a class="header-anchor" href="#上六-城復於隍-勿用師。自邑告命-貞吝。-象曰-城復於隍-其命亂也。" aria-label="Permalink to “上六，城復於隍，勿用師。自邑告命，貞吝。 象曰：“城復於隍”，其命亂也。”">​</a></h3><p>泰極則否，非力所支，故不可以師，其勢愈亂。貞，以命令諭眾，然終吝道也。故知者先幾，艱貞無咎，著戒未然也。</p>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
